private func tearDown() {
    stopPlayback()
    fileSource?.stop()
    fileSource = nil
    if isRunning {
        if hasMic { engine.inputNode.removeTap(onBus: 0) }
        engine.stop()
    }
    hasMic = false
    if let configObserver {
        NotificationCenter.default.removeObserver(configObserver)
        self.configObserver = nil
    }
    isRunning = false
}

